#!/usr/bin/env python3
"""Publish the checked measurements and a crawlable technical report."""
from pathlib import Path
import argparse, json, html, shutil, re

ap=argparse.ArgumentParser(description=__doc__)
ap.add_argument('--analysis',type=Path,required=True,help='Output of analyze_execution_report.py')
ap.add_argument('--repo',type=Path,default=Path(__file__).resolve().parents[1])
args=ap.parse_args();A=args.analysis.resolve();R=args.repo.resolve();U=R/'public'
d=json.loads((A/'report-metrics.json').read_text())
ex=json.loads((U/'data/execution/index.json').read_text())
episode=json.loads((A/'planning-episodes.json').read_text())
source_counts={}
for task in d['planning']['tasks']:
    source_counts[task['benchmark']]=source_counts.get(task['benchmark'],0)+1
    story=next((s for s in ex['stories'] if s['runs'][0]['taskId']==task['taskId']),None)
    task['executionId']=story['id'] if story else None
    raw=task['taskId'].split('--')[3] if '--' in task['taskId'] else task['taskId']
    task['label']=story['instruction'] if story else (raw.replace('_',' ').replace('-',' ') if task['benchmark'] in ['ScienceWorld','DiscoveryWorld','HumanCLAW'] else f"{task['benchmark']} task {source_counts[task['benchmark']]}")
d['execution']={k:ex[k] for k in ['runCount','roundCount','modelCount','toolCallCount']}
d['execution']['taskCount']=len(ex['stories'])
out=U/'data/report';out.mkdir(exist_ok=True)
(out/'metrics.json').write_text(json.dumps(d,separators=(',',':'))+'\n')
shutil.copy2(A/'planning-episodes.csv',out/'planning-episodes.csv')
shutil.copy2(A/'planning-episodes.json',out/'planning-episodes.json')
h=html.escape
models=d['planning']['models']
minimum=min(m['unsuccessfulTokenShare'] for m in models)*100
maximum=max(m['unsuccessfulTokenShare'] for m in models)*100
short={'astra':'Astra','sol':'Sol','fable':'Fable 5.1','gemini':'Gemini','qwen':'Qwen Max','qwen35-397b':'Qwen 397B','qwen35-27b':'Qwen 27B','opus55':'Opus 5.5','deepseek':'DeepSeek-1017'}
d['shortNames']=short
(out/'metrics.json').write_text(json.dumps(d,separators=(',',':'))+'\n')
intro='''<section id="technical-report" class="report-section" aria-labelledby="report-title"><div class="wrap">
<div class="report-heading"><div><p class="eyebrow">Anatomy of Task Completion</p><h2 id="report-title">Where Do Embodied Agents Get Stuck?</h2></div><a class="report-full-link" href="technical-report.html">Read the Full Analysis ↗</a></div>
<p class="report-deck">Nine models, the same 157 planning tasks. Follow the differences from benchmark scores to individual decisions.</p>
<div class="report-facts"><div><strong>19 / 157</strong><span>tasks completed by none of the nine models</span></div><div><strong>12 tasks</strong><span>completed by other models beyond Astra’s 126</span></div><div><strong>55–87%</strong><span>of recorded tokens spent on unsuccessful episodes</span></div></div>
<div class="report-tabs" role="tablist" aria-label="Analysis perspective">
<button type="button" role="tab" aria-selected="true" aria-controls="report-panel" id="report-tab-coverage" data-report="coverage">Shared Failures</button>
<button type="button" role="tab" aria-selected="false" aria-controls="report-panel" id="report-tab-resources" data-report="resources" tabindex="-1">Time &amp; Tokens</button>
<button type="button" role="tab" aria-selected="false" aria-controls="report-panel" id="report-tab-recovery" data-report="recovery" tabindex="-1">Error Recovery</button>
<button type="button" role="tab" aria-selected="false" aria-controls="report-panel" id="report-tab-representation" data-report="representation" tabindex="-1">Representation &amp; Feedback</button></div>
<div id="report-panel" class="report-panel" role="tabpanel" aria-labelledby="report-tab-coverage"><h3>Different Strengths, Shared Obstacles.</h3><p>Only eight tasks are completed by every model. At least one model completes 138 tasks; the remaining 19 defeat all nine in the recorded evaluation.</p><p><a href="technical-report.html#coverage">Read the task-level comparison ↗</a></p></div>
<div class="report-evidence-links"><a href="data/report/planning-episodes.csv" download>1,413 Episode Metrics ↓</a><a href="#execution-analysis">Inspect Videos &amp; Actions ↓</a><a href="technical-report.html#methods">Definitions &amp; Source Records ↗</a></div>
</div></section>'''
index=U/'index.html';s=index.read_text()
if '<!-- BEGIN TECHNICAL REPORT -->' in s:s=re.sub(r'<!-- BEGIN TECHNICAL REPORT -->.*?<!-- END TECHNICAL REPORT -->','<!-- BEGIN TECHNICAL REPORT -->'+intro+'<!-- END TECHNICAL REPORT -->',s,flags=re.S)
else:s=s.replace('<section id="execution-analysis"','<!-- BEGIN TECHNICAL REPORT -->'+intro+'<!-- END TECHNICAL REPORT -->\n<section id="execution-analysis"',1)
if 'technical-report.css' not in s:s=s.replace('</head>','<link rel="stylesheet" href="technical-report.css?v=20261020"><script src="technical-report.js?v=20261020" defer></script>\n</head>')
s=s.replace('<a href="#execution-analysis">Analysis</a>','<a href="#technical-report">Analysis</a>')
s=s.replace('7 Tasks · 33 Episodes · 9 Models',f"{len(ex['stories'])} Tasks · {ex['runCount']} Episodes · 9 Models")
index.write_text(s)

source_rows=[]
for m in models:
    cells=''.join(f'<td>{x["completed"]}/{x["n"]}</td>' for x in m['sourceResults'])
    source_rows.append(f'<tr><th scope="row">{h(m["name"])}</th>{cells}<td><strong>{m["completed"]}/157</strong></td></tr>')
resources=[]
for m in models:
    resources.append(f'<tr><th scope="row">{h(m["name"])}</th><td>{m["completed"]}/157</td><td>{m["time"]["median"]:.1f}</td><td>{m["time"]["q25"]:.1f}–{m["time"]["q75"]:.1f}</td><td>{m["unsuccessfulTokenShare"]*100:.1f}%</td><td>{m["tokens"]["n"]}/157</td><td>{m["recoveredAfterError"]}/{m["episodesWithExecutionErrors"]}</td></tr>')
sources=list(models[0]['sourceResults'])
table1='<div class="report-table-scroll"><table><caption>Completed Planning tasks, by source</caption><thead><tr><th>Model</th>'+''.join('<th>'+h(x['benchmark'])+'</th>' for x in sources)+'<th>All</th></tr></thead><tbody>'+''.join(source_rows)+'</tbody></table></div>'
table2='<div class="report-table-scroll"><table><caption>Planning outcomes, episode time, token allocation and recovery</caption><thead><tr><th>Model</th><th>Completed</th><th>Median time (s)</th><th>Time IQR (s)</th><th>Tokens in failed episodes</th><th>Usage records</th><th>Recovered / error episodes</th></tr></thead><tbody>'+''.join(resources)+'</tbody></table></div>'
profile_rows=[]
for p in d['profiles']:
    v=p['means'];profile_rows.append(f'<tr><th scope="row">{h(p["name"])}</th><td>{v[4]:.3f}</td><td>{v[5]:.3f}</td><td>{v[5]-v[4]:+.3f}</td><td>{v[6]:.1f}</td><td>{v[7]:.1f}</td></tr>')
table3='<div class="report-table-scroll"><table><caption>Region representation and downstream task completion</caption><thead><tr><th>Model</th><th>Box–mask IoU</th><th>Polygon IoU</th><th>Difference</th><th>Planning (%)</th><th>Manipulation (%)</th></tr></thead><tbody>'+''.join(profile_rows)+'</tbody></table></div>'
body=f'''<header class="report-cover"><a href="index.html#technical-report">← Embodied Agent Arena</a><p class="eyebrow">Technical Analysis · 20 October 2026</p><h1>From Local Competence to Complete Tasks</h1><p>Nine frontier VLM agents across five robotic capabilities, examined through measured outcomes, resource use and recorded execution.</p><nav aria-label="Report chapters"><a href="#coverage">01 Shared Failures</a><a href="#resources">02 Time &amp; Tokens</a><a href="#recovery">03 Recovery</a><a href="#progress">04 Physical Progress</a><a href="#representation">05 Representation</a><a href="#methods">Evidence</a></nav></header>
<main class="report-article">
<section id="coverage"><p class="eyebrow">01 / Common Tasks</p><h2>Model Diversity Does Not Remove the Shared Failure Set.</h2><p>Astra completes 126 of the 157 Planning tasks. Across all nine models, at least one succeeds on 138 tasks: only 12 more than Astra alone. Nineteen tasks remain incomplete for every model, while only eight are completed by all nine. The remaining tasks reveal substantial disagreement about what each agent can finish.</p><p><strong>The next evaluation target is the shared failure set, alongside the tasks on which models complement one another.</strong> The 19 common failures comprise four ALFRED tasks, four ALFWorld tasks, nine HumanCLAW tasks and two ScienceWorld tasks. These are observed outcomes on the shared task assignments; the union is an after-the-fact coverage count, not a tested routing policy.</p><figure class="report-figure"><img src="assets/analysis/planning-execution-profile.svg" alt="Shared task outcomes and token allocation across nine models" loading="lazy"><figcaption>Planning completion and unsuccessful-episode token allocation on 157 shared tasks.</figcaption></figure>{table1}<p><a href="index.html#technical-report">Explore individual tasks and model pairs →</a></p></section>
<section id="resources"><p class="eyebrow">02 / Resources</p><h2>Shorter Episodes and Fewer Decisions Are Different Advantages.</h2><p>Median Planning episode duration ranges from 57.1 seconds for DeepSeek-1017 to 280.7 seconds for Sol. Completion rates differ at the same time, so a short run can reflect either efficient success or early failure. The source filter on the project page shows these quantities together.</p><p>Between {minimum:.1f}% and {maximum:.1f}% of each model’s recorded tokens are spent on unsuccessful episodes. Even Astra, which completes 80.3% of the assignments, spends 55.5% of its recorded tokens on the 31 that it does not complete. <strong>Repeated attempts consume resources without necessarily satisfying the remaining goal conditions.</strong></p>{table2}<p>In the same HumanCLAW chair-navigation task, Astra completes in 18 rounds and 470.7 seconds; DeepSeek-1017 takes 65 rounds but 405.7 seconds. Model decisions, environment actions and wall time therefore need separate counters.</p><p><a href="index.html?analysis=time#execution-analysis">Compare the navigation videos and decisions →</a></p></section>
<section id="recovery"><p class="eyebrow">03 / Recovery</p><h2>An Error Can Be Repaired. A Goal Still Has to Be Completed.</h2><p>Opus 5.5 completes 48 of its 105 Planning episodes that contain a recorded execution error. Those recovered episodes account for 48 of its 76 successes. The error records include malformed code and rejected API use; this measures the observed agent-and-interface execution, rather than a separate coding benchmark.</p><p>The Archaeology Dating task makes the distinction visible. Opus 5.5’s first two rounds fail before an environment action. It then collects tools, excavates the sites, reads artifact ages and places the flag at the oldest site, reaching the native score of 1.0 in round seven. DeepSeek-1017 reaches 0.5 by round five, then its last three rounds end in code errors with no further environment steps.</p><p><strong>Recovery is useful when it changes the task state.</strong> A revised response by itself is not evidence that the goal is any closer.</p><p><a href="index.html?analysis=recovery#execution-analysis">Inspect all seven rounds and their returned feedback →</a></p></section>
<section id="progress"><p class="eyebrow">04 / Physical Progress</p><h2>A Valid Action Is Not a Completed Subgoal.</h2><p>On CALVIN sequence 0526, Opus 5.5 completes five subgoals using 338 action submissions, 18 model calls and 229.4 seconds. Gemini uses 501 action submissions and 464 state observations, yet finishes with zero of five subgoals after 36 calls and 796.5 seconds. Its final stop is the token budget. The current-subgoal queries show Opus advancing through retrieval, storage, stacking and the light switch; Gemini’s retained queries remain on the first lifting goal.</p><p>ALFRED provides a complementary example: Gemini completes the instruction to clean a soap bar and place it in the bathtub, while DeepSeek-1017 finishes with one of three goal conditions met. Both use eight model calls. On RoboCasa’s left-drawer task, Fable 5.1 completes in 20 rounds while Sol reaches its 24-round ceiling without the required final state.</p><p><strong>Count verified changes in the task state, then relate them to actions, observations and elapsed time.</strong> This separates purposeful progress from activity that leaves the goal unsatisfied.</p><figure class="report-figure"><img src="assets/analysis/execution-progress.svg" alt="Archaeology score progression and CALVIN action, observation and outcome comparison" loading="lazy"><figcaption>Native progress, actions and elapsed time reveal different parts of an execution.</figcaption></figure><p><a href="index.html?analysis=sequence#execution-analysis">CALVIN sequence →</a> · <a href="index.html?analysis=goal#execution-analysis">ALFRED goal conditions →</a> · <a href="index.html?analysis=drawer#execution-analysis">RoboCasa drawer →</a></p><h3>Which budget actually stopped the episode?</h3><p>In the selected BEHAVIOR-1K toolbox task, none of the eight recorded models completes the native goal. Episodes run for approximately 12–133 minutes and stop on token or round limits despite a 180-minute time ceiling. Simply allowing more wall time would leave those observed limits in place.</p><p><a href="index.html?analysis=horizon#execution-analysis">Inspect the resource ceilings and stopping reasons →</a></p></section>
<section id="representation"><p class="eyebrow">05 / Representation and Feedback</p><h2>Better Observations and Richer Outputs Need Effective Control.</h2><p>Astra has the lowest pose errors and strongest Planning result; Gemini has the lowest numerical spatial error; Opus 5.5 leads both affordance-overlap metrics and Manipulation. These rank changes make a single proxy inadequate for selecting an embodied generalist.</p>{table3}<p>Direct polygons increase mean region overlap for eight of nine models on the same 70 Affordance cases. Qwen 397B is the exception (0.116 box–mask IoU versus 0.092 polygon IoU). The representation can fit a region more closely, but that improvement is not itself a test of grasping or task execution.</p><p>The paired observation experiment supplies a stronger intervention: adding current RGB at every round changes Astra’s CALVIN success from 30% to 0%, and Fable’s from 0% to 40%, under the matched source budgets. Astra’s median input tokens rise from 0.32M to 1.21M while median submitted actions fall from 1,795 to 481. Extra feedback therefore changes both the available evidence and how the agent allocates its interaction budget.</p><p><strong>An embodied generalist must use evidence to finish every required condition, before its decision and interaction budgets run out.</strong> The full benchmark measures that end-to-end outcome; the execution traces show where it is lost.</p><p><a href="paper.pdf">See the paired observation experiment in the paper →</a></p></section>
<section id="methods"><p class="eyebrow">Evidence and Definitions</p><h2>From Recorded Outputs to Reproducible Counts.</h2><p>The Planning analysis uses 1,413 source reports: nine models evaluated on the same 157 task assignments. All report SHA-256 hashes were checked against the supplied log manifest. Native task identity was checked separately for the HumanCLAW wrappers whose model-specific canonical names differ. Completion counts reproduce the adopted main-table Planning results.</p><p>Time is reported episode wall time, or the last recorded agent-loop time where no total duration is supplied. It includes reported setup and environment interaction, so it is not model inference latency. IQR is the 25th–75th percentile. Token totals use recorded input plus output usage. Missing usage is excluded: coverage is shown for every model. Failure token share is the sum in unsuccessful episodes divided by the sum in all episodes with recorded usage. Recovery means native final success after an earlier recorded execution error; budget guards and timed-out rounds are excluded from that error count.</p><p>The video explorer contains {len(ex['stories'])} same-task groups, {ex['runCount']} episodes and {ex['roundCount']:,} recorded rounds. Its Manipulation examples include later observation configurations; the original Baseline aggregate remains in the main results table. Per-episode settings, stop limits and source hashes accompany each trace. Native tool events are matched to round completion timestamps; any events without a close timestamp match remain separately available in the trace. Video excerpts and saved-observation sequences retain their own playback clock.</p><p><a href="author-source.zip" download>Author manuscript source (ZIP) ↓</a> · <a href="assets/analysis/editable-figures.zip" download>Editable figures (draw.io, SVG, PDF, PNG) ↓</a> · <a href="data/report/planning-episodes.csv" download>Planning episode metrics (CSV) ↓</a> · <a href="data/report/metrics.json">Analysis data (JSON) ↗</a> · <a href="data/execution/episodes.csv" download>Video episode metrics (CSV) ↓</a> · <a href="execution-guide.html">All execution comparisons ↗</a></p></section></main>'''
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>From Local Competence to Complete Tasks — Embodied Agent Arena</title><meta name="description" content="A detailed nine-model analysis of shared planning failures, time and token use, recovery, action progress and observation design, with task videos and source records."><link rel="canonical" href="https://embodied-agent-arena.github.io/embodied-agent-arena/technical-report.html"><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="technical-report.css?v=20261020"></head><body class="report-page">'+body+'</body></html>'
(U/'technical-report.html').write_text(page)
ledger=[
 ('Shared failures','19/157; 8/157 common successes; union 138/157', '1,413 Planning report outcomes; matched manifest task_id','planning.tasks','Main Results + execution appendix','Shared Failures'),
 ('Complementarity','138 − 126 = 12 tasks beyond Astra','Same-task union; descriptive, not a tested selector','planning.additionalOverAstra','Execution appendix','Shared Failures'),
 ('Failed-episode token share',f'{minimum:.1f}–{maximum:.1f}%; Astra 55.5%','Sum observed input/output tokens; denominator only records with usage','planning.models','Execution appendix','Time & Tokens'),
 ('Recovery','Opus 5.5: 48/105 error episodes eventually complete','Native success after earlier execution error, exclude budget guards/timeouts','planning.models','Execution appendix','Error Recovery'),
 ('CALVIN progress','Opus 5/5,338 action calls; Gemini 0/5,501 action calls','Same sequence0526, per-record settings, native verifier and gateway traces','data/execution','Execution appendix','Execution explorer'),
 ('Representation','Polygon IoU greater for8/9 models','70 identical task inputs; one polygon run vs repeated boxes','profiles','Existing Affordance appendix + report','Representation & Feedback')]
lines=['# Claim ledger','', '| Claim | Value | Scope / calculation | Data field | Manuscript | Website |','|---|---|---|---|---|---|']
lines+=['| '+' | '.join(x)+' |' for x in ledger]
(R/'docs/EXECUTION_CLAIMS.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'tasks':len(ex['stories']),'episodes':ex['runCount'],'planningReports':1413,'reportBytes':len(page),'claimCount':len(ledger)}))
